SELECT game_id AS "gameId", provider_id AS "providerId", state_key AS "stateKey", value_type_id AS "valueTypeId", max_value AS "maxValue", duration_ms AS "durationMs", refresh_policy_type_id AS "refreshPolicyTypeId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.provider_state_fields WHERE game_id = #{gameId}
AND provider_id = #{providerId}
ORDER BY provider_id, state_key
